import java.util.*;

class Solution {
  public List<Integer> boundaryOfBinaryTree(TreeNode root) {
    List<Integer> res = new ArrayList<>();
    if (root == null) return res;
    res.add(root.val);
    if (root.left == null && root.right == null) return res;
    for (TreeNode cur = root.left; cur != null && !isLeaf(cur); cur = cur.left != null ? cur.left : cur.right) res.add(cur.val);
    leaves(root, res);
    Deque<Integer> right = new ArrayDeque<>();
    for (TreeNode cur = root.right; cur != null && !isLeaf(cur); cur = cur.right != null ? cur.right : cur.left) right.push(cur.val);
    res.addAll(right);
    return res;
  }

  private void leaves(TreeNode node, List<Integer> res) {
    if (node == null) return;
    if (isLeaf(node)) {
      res.add(node.val);
      return;
    }
    leaves(node.left, res);
    leaves(node.right, res);
  }

  private boolean isLeaf(TreeNode n) {
    return n.left == null && n.right == null;
  }
}
